const stamp=(s:string)=>new Date(s).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'});
const day=(s:string)=>new Date(s).toLocaleDateString(undefined,{day:'numeric',month:'short'});
const local=(s?:string)=>{const d=s?new Date(s):new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
function useComms(){const app=useApp();return {...app,base:'/societies/'+app.tenant+'/communications'};}
function useDebounce(value:string){const [v,set]=useState(value);useEffect(()=>{const timer=setTimeout(()=>set(value),250);return()=>clearTimeout(timer)},[value]);return v;}
export function CommunicationNotifications(){const {tenant,base}=useComms();const [open,setOpen]=useState(false),[live,setLive]=useState(false);const client=useQueryClient();const q=useLoad(base+'/notifications',!!tenant);useEffect(()=>{if(!tenant)return;let disposed=false,connection:any;import('@microsoft/signalr').then(async signal=>{if(disposed)return;connection=new signal.HubConnectionBuilder().withUrl('/realtime/communications').withAutomaticReconnect().configureLogging(signal.LogLevel.Error).build();connection.on('changed',()=>client.invalidateQueries({predicate:q=>String(q.queryKey[0]).includes('/communications')}));connection.onreconnected(()=>setLive(true));connection.onclose(()=>setLive(false));try{await connection.start();if(!disposed)setLive(true)}catch{setLive(false)}});return()=>{disposed=true;connection?.stop()}},[tenant,client]);if(!tenant)return null;return <><button className="icon-btn notification-bell" aria-label="Open notification center" onClick={()=>setOpen(true)}><Bell size={18}/>{q.data?.unread>0&&<span>{q.data.unread}</span>}</button>{open&&<Drawer title="Notification center" onClose={()=>setOpen(false)}><div className="comms-drawer-body"><p className="comms-muted">{live?'Live updates connected':'Updates refresh automatically'} · {q.data?.unread||0} unread</p><button onClick={async()=>{await api(base+'/notifications/read','POST');q.refetch()}}>Mark all read</button><DataState query={q}>{q.data?.items.map((n:any)=><Link key={n.id} className={'notification-item '+(!n.readAt?'unread':'')} to={n.link} onClick={async()=>{await api(base+'/notifications/'+n.id+'/read','POST');setOpen(false);q.refetch()}}><span className="comms-avatar"><Bell size={16}/></span><div><strong>{n.title}</strong><small>{day(n.at)} · {stamp(n.at)}</small></div>{!n.readAt&&<i/>}</Link>)}{q.data?.items.length===0&&<Empty title="You’re all caught up" text="Real messages, notices and updates will appear here."/>}</DataState></div></Drawer>}</>}
export default function Communications(){const {tenant,can}=useComms();if(!tenant)return <Empty title="Select a society" text="Choose an authorized workspace to open communications."/>;
 const nav=[['inbox','Inbox',Inbox,true],['broadcasts','Broadcasts',Send,true],['content','Templates',FileText,can('communications.templates')||can('communications.send')],['automations','Automations',Clock,can('communications.automations')],['insights','Delivery',CheckCheck,can('communications.send')||can('communications.analytics')],['settings','Settings',Settings,true]] as const;
 const broadcasts=[{id:'announcements',label:'Announcements',content:<Announcements/>},{id:'campaigns',label:'Campaigns',content:<Campaigns/>,visible:can('communications.send')},{id:'scheduled',label:'Scheduled',content:<Campaigns scheduled/>,visible:can('communications.send')},{id:'review',label:'Approvals',content:<Campaigns review/>,visible:can('communications.approve')}];
 const aliases:Record<string,[string,string]>={announcements:['broadcasts','announcements'],campaigns:['broadcasts','campaigns'],schedules:['broadcasts','scheduled'],review:['broadcasts','review'],templates:['content','templates'],audiences:['content','audiences'],delivery:['insights','delivery'],analytics:['insights','analytics'],preferences:['settings','preferences']};
 return <div className="communication-shell"><aside className="communication-rail"><div className="comms-brand"><MessageCircle size={18}/><strong>Messages</strong><small>COMMUNICATION CENTER</small></div><nav>{nav.filter(v=>v[3]).map(([path,title,Icon])=><NavLink key={path} to={'/app/communications/'+path}><Icon size={15}/>{title}</NavLink>)}</nav><div className="comms-rail-note"><ShieldCheck size={16}/><p>Connected by purpose.<br/>Protected by permissions.</p></div></aside><section className="communication-content"><Routes><Route index element={<WorkspaceAlias to="/app/communications/inbox"/>}/><Route path="inbox" element={<UnifiedInbox/>}/><Route path="inbox/:id" element={<UnifiedInbox/>}/><Route path="received/:id" element={<Received/>}/><Route path="broadcasts" element={<WorkspaceSections label="Broadcasts & approvals" sections={broadcasts}/>}/><Route path="content" element={<WorkspaceSections label="Content & audiences" sections={[{id:'templates',label:'Message templates',content:<Templates/>,visible:can('communications.templates')||can('communications.send')},{id:'audiences',label:'Saved audiences',content:<Audiences/>,visible:can('communications.send')}]}/>}/><Route path="automations" element={<Automations/>}/><Route path="insights" element={<WorkspaceSections label="Delivery & insights" sections={[{id:'delivery',label:'Delivery tracking',content:<Delivery/>,visible:can('communications.send')},{id:'analytics',label:'Communication analytics',content:<Analytics/>,visible:can('communications.analytics')}]}/>}/><Route path="settings" element={<WorkspaceSections label="Communication settings" sections={[{id:'providers',label:'Provider accounts',content:<ProviderSettings/>,visible:can('communications.accounts')},{id:'preferences',label:'My preferences',content:<Preferences/>}]}/>}/>{Object.entries(aliases).map(([path,[target,view]])=><Route key={path} path={path} element={<WorkspaceAlias to={'/app/communications/'+target} query={{view}}/>}/>)}</Routes></section></div>
}
function UnifiedInbox(){const {id}=useParams();const {base,scope,can}=useComms();const navigate=useNavigate();const [search,setSearch]=useState(''),[create,setCreate]=useState(false);const debounced=useDebounce(search);const params=new URLSearchParams(location.search);if(scope)params.set('workspace',scope);if(debounced)params.set('search',debounced);const path=base+'/inbox?'+params;const q=useInfiniteQuery({queryKey:[path],initialPageParam:'',queryFn:({pageParam})=>api(path+pageParam),getNextPageParam:r=>r.hasMore?'&before='+encodeURIComponent(r.next.before)+'&beforeId='+r.next.beforeId:undefined,refetchInterval:5000});const rows=q.data?.pages.flatMap(p=>p.items)||[];return <div className={'inbox-layout '+(id?'has-conversation':'')}><section className="conversation-list"><header><div><span className="eyebrow">YOUR COMMUNITY, CONNECTED</span><h1>Messages<span>{rows.length}</span></h1></div><button className="comms-icon" aria-label="Start a conversation" onClick={()=>setCreate(true)}><Plus size={20}/></button></header><div className="comms-search"><Search size={15}/><input aria-label="Search conversations" placeholder="Search conversations…" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="workspace-filter-row"><label>Channel<select aria-label="Conversation channel" value={params.get('channel')||''} onChange={e=>{const next=new URLSearchParams(location.search);e.target.value?next.set('channel',e.target.value):next.delete('channel');navigate('/app/communications/inbox?'+next)}}><option value="">All channels</option>{(can('communications.inbox')?['WhatsApp','Email','SMS','InApp']:['InApp']).map(c=><option key={c} value={c}>{c==='InApp'?'In-app messages':c}</option>)}</select></label></div><div className="workspace-filter-row"><label>View<select aria-label="Inbox view" value={params.get('filter')||''} onChange={e=>{const next=new URLSearchParams(location.search);e.target.value?next.set('filter',e.target.value):next.delete('filter');navigate('/app/communications/inbox?'+next)}}>{[['','All conversations'],['Unread','Unread'],['Assigned','Assigned to me'],['Team','Team inbox'],['Groups','Chapter groups'],['Unassigned','Unassigned']].filter(([v])=>!['Assigned','Team','Unassigned'].includes(v)||can('communications.inbox')).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label></div><DataState query={q}><div className="conversation-rows">{rows.map((c:any)=><Link key={c.id} className={'conversation-row '+(id===c.id?'selected':'')} to={'/app/communications/inbox/'+c.id+location.search}><span className={'comms-avatar '+(c.kind==='Group'?'group':'')}>{c.kind==='Group'?<Users size={20}/>:c.subject.slice(0,2).toUpperCase()}<i className={'channel-dot '+c.channel.toLowerCase()}/></span><div><div className="conversation-row-top"><strong>{c.subject}</strong><time>{stamp(c.lastAt)}</time></div><p>{c.preview||'Start the conversation'}</p><div className="conversation-row-foot"><small>{c.chapter||c.channel}</small>{c.unread>0?<b>{c.unread}</b>:c.priority!=='Normal'&&<Badge>{c.priority}</Badge>}</div></div></Link>)}{rows.length===0&&<Empty title="Room for a new conversation" text="Reach out to a permitted member or your chapter team."/>}{q.hasNextPage&&<button className="comms-load" onClick={()=>q.fetchNextPage()}>Load more conversations</button>}</div></DataState></section>{id?<ConversationPane key={id} id={id}/>:<div className="conversation-welcome"><div className="welcome-orbit"><MessageCircle size={50}/></div><span className="eyebrow">ONE COMMUNITY. MANY CONVERSATIONS.</span><h2>A little conversation.<br/>A stronger connection.</h2><p>Bring your chapter closer. Start a private conversation, connect with your team, or catch up on what matters.</p><button className="primary" onClick={()=>setCreate(true)}>Start a conversation <ArrowRight size={15}/></button><small><ShieldCheck size={14}/>Your conversations follow society and member privacy rules.</small></div>}{create&&<NewConversation onClose={()=>{setCreate(false);q.refetch()}}/>}</div>}
function NewConversation({onClose}:any){const {base,tenant,scope,can}=useComms();const nav=useNavigate(),action=useAction();const [kind,setKind]=useState('Direct'),[title,setTitle]=useState(''),[search,setSearch]=useState(''),[target,setTarget]=useState(''),[ids,setIds]=useState<string[]>([]),[unit,setUnit]=useState(scope||''),[posting,setPosting]=useState('Members'),[channel,setChannel]=useState('InApp'),[account,setAccount]=useState('');const members=useLoad('/societies/'+tenant+'/membership/members?pageSize=100&search='+encodeURIComponent(useDebounce(search)));const setup=useLoad(base+'/setup'),accounts=useLoad(base+'/accounts',can('communications.inbox'));return <Drawer title="Start a conversation" onClose={onClose}><form className="comms-drawer-body" onSubmit={async e=>{e.preventDefault();if(await action.run(async()=>{const result=await api(base+'/conversations','POST',{subject:title||members.data?.items.find((m:any)=>m.id===target)?.fullName||'Chapter conversation',kind,membershipId:target||null,unitId:unit||null,memberIds:ids,posting,channel,accountId:account||null});onClose();nav('/app/communications/inbox/'+result.id)},'Conversation opened'))onClose()}}><div className="comms-choice-tabs">{[['Direct','Private message'],['Team','Chapter team'],...(can('communications.groups')?[['Group','Chapter group']]:[])].map(([v,label])=><button type="button" key={v} className={kind===v?'active':''} onClick={()=>setKind(v)}>{label}</button>)}</div><Field label="Conversation title" value={title} onChange={(e:any)=>setTitle(e.target.value)} maxLength={160}/>{kind!=='Direct'&&<Field label="Organization"><select required value={unit} onChange={e=>setUnit(e.target.value)}><option value="">Select organization</option>{setup.data?.organizations.map((u:any)=><option value={u.id} key={u.id}>{u.name}</option>)}</select></Field>}{kind==='Team'&&can('communications.inbox')&&<><Field label="Channel"><select value={channel} onChange={e=>setChannel(e.target.value)}>{['InApp','Email','SMS','WhatsApp'].map(v=><option key={v}>{v}</option>)}</select></Field>{channel!=='InApp'&&<Field label="Sending account"><select required value={account} onChange={e=>setAccount(e.target.value)}><option value="">Choose a verified account</option>{accounts.data?.filter((a:any)=>a.channel===channel).map((a:any)=><option value={a.id} key={a.id}>{a.name} · {a.verified?'Verified':'Not verified'}</option>)}</select></Field>}</>}{(kind==='Direct'||kind==='Group'||channel!=='InApp')&&<><Field label="Find a permitted member" value={search} onChange={(e:any)=>setSearch(e.target.value)}/><div className="comms-member-picker">{members.data?.items.map((m:any)=><label key={m.id}><input type={kind==='Group'?'checkbox':'radio'} name="recipient" checked={kind==='Group'?ids.includes(m.id):target===m.id} onChange={()=>kind==='Group'?setIds(ids.includes(m.id)?ids.filter(v=>v!==m.id):[...ids,m.id]):setTarget(m.id)}/><span className="comms-avatar">{m.fullName.slice(0,2)}</span><span><strong>{m.fullName}</strong><small>{m.chapter}</small></span></label>)}</div></>}{kind==='Group'&&<Field label="Who can post?"><select value={posting} onChange={e=>setPosting(e.target.value)}>{['Members','Admins','Officers','Approval'].map(v=><option key={v}>{v}</option>)}</select></Field>}<p className="comms-muted">Private messages are visible to participants. Chapter team inquiries are explicitly shared with authorized officers. No contact details are exposed by starting a conversation.</p><button className="primary" disabled={action.busy||kind==='Direct'&&!target}>Open conversation <ArrowRight size={15}/></button></form></Drawer>}
function ConversationPane({id}:{id:string}){const {base,notify}=useComms();const client=useQueryClient();const q=useLoad(base+'/conversations/'+id);const path=base+'/conversations/'+id+'/messages';const messages=useInfiniteQuery({queryKey:[path],initialPageParam:'',queryFn:({pageParam})=>api(path+pageParam),getNextPageParam:r=>r.hasMore?'?before='+encodeURIComponent(r.next.before)+'&beforeId='+r.next.beforeId:undefined,refetchInterval:5000});const [text,setText]=useState(''),[internal,setInternal]=useState(false),[context,setContext]=useState(false),[manage,setManage]=useState(false),[busy,setBusy]=useState(false),[attachment,setAttachment]=useState<File|null>(null);const scroll=useRef<HTMLDivElement>(null);const rows=messages.data?.pages.flatMap(p=>p.items).reverse()||[];const virtual=useVirtualizer({count:rows.length,getScrollElement:()=>scroll.current,estimateSize:()=>90,overscan:8});useEffect(()=>{if(q.data)api(base+'/conversations/'+id+'/read','POST').then(()=>client.invalidateQueries({queryKey:[base+'/notifications']})).catch(()=>{})},[id,q.data?.self]);useEffect(()=>{if(rows.length)virtual.scrollToIndex(rows.length-1,{align:'end'})},[rows.length]);async function send(e:any){e.preventDefault();if(!text.trim()&&!attachment)return;const key=crypto.randomUUID();const before=client.getQueryData([path]);const body=text.trim()||'Attachment';client.setQueryData([path],(d:any)=>d?{...d,pages:d.pages.map((p:any,i:number)=>i? p:{...p,items:[{id:'pending-'+key,senderId:q.data.self,body,status:'Sending',at:new Date().toISOString(),attachments:[],internal},...p.items]})}:d);setText('');setBusy(true);try{const message=await api(base+'/conversations/'+id+'/messages','POST',{body,clientKey:key,hold:!!attachment,internal});if(attachment){const csrf=await api('/auth/csrf');const response=await fetch('/api/v1'+base+'/messages/'+message.id+'/attachments',{method:'POST',headers:{'Content-Type':attachment.type,'X-CSRF-TOKEN':csrf.token,'X-Filename':attachment.name},body:attachment});if(!response.ok)throw new Error((await response.json()).title||'Attachment upload failed');if(q.data.conversation.channel!=='InApp'&&!internal)await api(base+'/messages/'+message.id+'/send','POST');setAttachment(null)}await client.invalidateQueries({predicate:q=>String(q.queryKey[0]).includes('/communications')});}catch(err){client.setQueryData([path],before);setText(body);notify((err as Error).message)}finally{setBusy(false)}}if(!q.data)return <DataState query={q}/>;const c=q.data.conversation;return <><section className="conversation-pane"><header className="chat-header"><Link className="comms-mobile-back" to="/app/communications/inbox"><ArrowLeft size={19}/></Link><span className="comms-avatar">{c.kind==='Group'?<Users size={20}/>:c.subject.slice(0,2).toUpperCase()}</span><div><h2>{c.subject}</h2><small>{c.kind==='Direct'?'Private member conversation':c.kind==='Team'?'Shared chapter team inbox':'Chapter group'} · {c.channel}</small></div><button className="comms-icon" aria-label="Conversation context" onClick={()=>setContext(true)}><Info size={18}/></button>{q.data.canManage&&<button className="comms-icon" aria-label="Manage conversation" onClick={()=>setManage(true)}><MoreHorizontal size={19}/></button>}</header><div className="chat-status-line"><ShieldCheck size={13}/><span>{c.kind==='Direct'?'Only participants can access this conversation.':'Access follows membership and organizational permissions.'}</span><Badge>{c.status}</Badge></div><DataState query={messages}><div className="message-history" ref={scroll}>{messages.hasNextPage&&<button className="comms-load" onClick={()=>messages.fetchNextPage()}>Load earlier messages</button>}<div style={{height:virtual.getTotalSize(),position:'relative'}}>{virtual.getVirtualItems().map(v=>{const m=rows[v.index];return <div key={m.id} data-index={v.index} ref={virtual.measureElement} className={'message-position '+(m.senderId===q.data.self?'outgoing':'incoming')} style={{position:'absolute',top:0,left:0,width:'100%',transform:`translateY(${v.start}px)`}}><div className={'message-bubble '+(m.internal?'internal':'')}><small>{m.internal?'INTERNAL NOTE':m.sender||'You'}</small><p>{m.removedAt?'[Message removed]':m.body}</p>{m.attachments?.map((f:any)=><a className="message-file" key={f.id} href={'/api/v1'+base+'/attachments/'+f.id} target="_blank" rel="noreferrer">{f.contentType==='image/png'?<img loading="lazy" alt={f.name||'Shared photograph'} src={'/api/v1'+base+'/attachments/'+f.id}/>:<><Paperclip size={14}/>{f.name||'Document'}</>}</a>)}<footer><time>{stamp(m.at)}</time><span>{m.status==='Read'?<CheckCheck size={13}/>:m.status==='Sending'?<Clock size={12}/>:<Check size={12}/>} {m.status}</span><button aria-label="Report message" onClick={()=>{const reason=prompt('Reason for reporting this message');if(reason)api(base+'/messages/'+m.id+'/report','POST',{reason}).then(()=>notify('Report saved')).catch(e=>notify(e.message))}}>Report</button></footer></div></div>})}</div>{rows.length===0&&<div className="chat-empty"><MessageCircle size={30}/><p>A thoughtful conversation starts with hello.</p></div>}</div></DataState><form className={'message-composer '+(internal?'note-mode':'')} onSubmit={send}>{q.data.canInternal&&<label className="internal-toggle"><input type="checkbox" checked={internal} onChange={()=>setInternal(!internal)}/>Internal note</label>}{attachment&&<div className="attachment-staged"><Paperclip size={14}/>{attachment.name}<button type="button" onClick={()=>setAttachment(null)}><X size={13}/></button></div>}<div className="composer-line"><label className="comms-icon attachment-button" aria-label="Attach file"><Paperclip size={19}/><input type="file" accept="image/png,application/pdf" onChange={e=>setAttachment(e.target.files?.[0]||null)}/></label><textarea aria-label="Message text" placeholder={internal?'Add a private team note…':'Write a message…'} value={text} onChange={e=>setText(e.target.value)} maxLength={12000} rows={2} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send(e)}}}/><button className="send-message" aria-label="Send message" disabled={busy||(!text.trim()&&!attachment)}><Send size={18}/></button></div><small>{internal?'Visible only to authorized inbox staff.':'Enter to send · Shift + Enter for a new line'}</small></form></section><aside className="conversation-context-desktop"><ContextCard data={q.data}/></aside>{context&&<Drawer title="Conversation details" onClose={()=>setContext(false)}><div className="comms-drawer-body"><ContextCard data={q.data}/><button onClick={()=>api(base+'/conversations/'+id+'/mute','POST').then(()=>notify('Conversation mute preference updated')).catch(e=>notify(e.message))}>Toggle mute</button></div></Drawer>}{manage&&<ManageConversation data={q.data} onClose={()=>{setManage(false);q.refetch()}}/>}</>}
function ContextCard({data}:any){const {base}=useComms();const card=data.context;return <div className="context-card"><span className="eyebrow">MEMBER CONTEXT</span>{card?<><span className="context-avatar">{card.fullName.slice(0,2)}</span><h3>{card.fullName}</h3><p>{card.chapter}</p><Badge>{card.status}</Badge><dl><dt>Region</dt><dd>{card.region||'Not available'}</dd><dt>Designation</dt><dd>{card.designation||'Member'}</dd><dt>Contact sharing</dt><dd>{card.contacts?'Permitted':'Private'}</dd></dl><Link to={'/app/members/profile/'+card.id}>Open authorized CRM profile <ChevronRight size={13}/></Link></>:<><span className="context-avatar"><Users size={32}/></span><h3>{data.conversation.kind==='Group'?'Chapter group':'Conversation context'}</h3><p>Personal CRM fields appear only when directory permissions allow.</p></>}<hr/><h4>Participants</h4>{data.participants.filter((p:any)=>!p.leftAt).map((p:any)=><div className="context-participant" key={p.id}><span className="comms-avatar">{p.fullName.slice(0,2)}</span><div><strong>{p.fullName}</strong><small>{p.role}</small></div></div>)}<div className="context-privacy"><ShieldCheck size={16}/><p>Private messages are never added to a regional or society team inbox.</p></div><Link to={base.includes('/societies/')?'/app/communications/preferences':'#'}>Communication preferences</Link></div>}
function ManageConversation({data,onClose}:any){const {base}=useComms(),action=useAction();const [form,setForm]=useState({...data.conversation});const team=useLoad(base+'/team'+(data.conversation.unitId?'?unit='+data.conversation.unitId:''),data.conversation.kind==='Team');const people=useLoad('/societies/'+useComms().tenant+'/membership/members?pageSize=100');return <Drawer title="Manage shared conversation" onClose={onClose}><form className="comms-drawer-body" onSubmit={async e=>{e.preventDefault();if(await action.run(()=>api(base+'/conversations/'+form.id,'PUT',form)))onClose()}}><Field label="Status"><select value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{['Open','Pending','Resolved','Archived'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Priority"><select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}>{['Normal','Important','Urgent'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Assign to authorized officer"><select value={form.assignedTo||''} onChange={e=>setForm({...form,assignedTo:e.target.value||null})}><option value="">Unassigned</option>{(team.data||data.participants.map((p:any)=>({id:p.userId,fullName:p.fullName}))).map((p:any)=><option key={p.id} value={p.id}>{p.fullName}</option>)}</select></Field><Field label="Follow-up date" type="datetime-local" value={form.followUpAt?local(form.followUpAt):''} onChange={(e:any)=>setForm({...form,followUpAt:e.target.value?new Date(e.target.value).toISOString():null})}/><Field label="Resolution notes"><textarea value={form.resolution} onChange={e=>setForm({...form,resolution:e.target.value})}/></Field><button className="primary" disabled={action.busy}>Save conversation</button>{form.kind==='Group'&&<><h3>Current group members</h3>{data.participants.filter((p:any)=>!p.leftAt&&p.userId!==data.self).map((p:any)=><div className="comms-row" key={p.userId}><span>{p.fullName}</span><button type="button" onClick={()=>action.run(()=>api(base+'/groups/'+form.id+'/members/'+p.userId,'DELETE'),'Participant removed').then(()=>onClose())}>Remove</button></div>)}<h3>Add permitted group member</h3>{people.data?.items.map((p:any)=><div className="comms-row" key={p.id}><span>{p.fullName}</span><button type="button" onClick={()=>action.run(()=>api(base+'/groups/'+form.id+'/members','POST',{membershipId:p.id,role:'Member',responsibilities:'Group member',startsAt:new Date().toISOString(),endsAt:null}))}>Add</button></div>)}</>}</form></Drawer>}

const filters=['Chapter','Region','District','Country','State','Status','Category','Officer','Committee','Language','JoinedAfter','JoinedBefore','EventRegistration','EventRsvp','EventAttendance'];
